from math import sqrt, floor

def num_divisors(n):
    count = 0
    for i in range(1, int(sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def calculate_sum(a, b, c):
    result = 0
    for n in range(a, b + 1):
        for m in range(n + 1, b + 1):
            for k in range(m + 1, c + 1):
                result += num_divisors(n * m * k)
    return result % (1 << 30)

