def longest_subarray_without_unique_most_frequent_value(n, a):
    freqs = {}
    for num in a:
        freqs[num] = freqs.get(num, 0) + 1

    max_freq = max(freqs.values())
    subarray_max_freqs = {}

    def has_common_max_freq(subarray):
        seen = set()
        for num in subarray:
            if freqs[num] in subarray_max_freqs and freqs[num] == max_freq:
                if freqs[num] not in seen:
                    seen.add(freqs[num])
        return len(seen) >= 2

    longest = 0
    for i in range(n):
        for j in range(i, n):
            if has_common_max_freq(a[i:j+1]):
                if j - i > longest:
                    longest = j - i

    return longest

