def find_longest_subarray(arr):
    frequency = {}
    left = 0
    max_length = 0
    frequency_count = {}

    for right in range(len(arr)):
        if arr[right] in frequency_count:
            frequency_count[arr[right]] += 1
        else:
            frequency_count[arr[right]] = 1

        if frequency.get(arr[right], 0) > max(frequency_count.values()):
            max_length = max(max_length, right - left + 1)

        while min(frequency_count.values()) >= 2:
            frequency[arr[left]] -= 1
            left += 1
            if frequency_count[arr[left - 1]] == 0:
                del frequency_count[arr[left - 1]]
            if frequency_count[arr[left]] == 1:
                del frequency_count[arr[left]]
            if frequency[arr[left - 1]] == 0:
                del frequency_count[arr[left - 1]]
            if frequency_count.get(arr[left - 1], 0) <= 1:
                del frequency_count[arr[left - 1]]

            if frequency[arr[left - 1]] == 0:
                del frequency[arr[left - 1]]
            if frequency_count.get(arr[left - 1], 0) <= 1:
                del frequency_count[arr[left - 1]]

            if frequency_count.get(arr[left], 0) > max(frequency_count.values()):
                max_length = max(max_length, right - left + 1)

    return max_length

