from collections import defaultdict

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def generate_prime_prefixes(primes, length):
    prefix_primes = [0] * (length + 2)
    primes_set = set(primes)
    for i in range(2, length + 1):
        prefix_primes[i] = int(bin(i).count('1'))
    for prime in primes:
        if prime not in primes_set:
            return []
    prefix_primes = [0] + prefix_primes + [2]  # Adding base cases
    for prime in primes:
        for i in range(prime + 1, len(prefix_primes)):
            for mask_size in range(1, len(prefix_primes)//prime):
                prefix_add_number = (i + mask_size*(prefix_primes[i+1] - prefix_primes[i+prime*mask_size-1])) % prefix_primes[i+prime*mask_size]
                prefix_add_number = int(bin(prefix_add_number).count('1')) % prefix_primes[i+prime*mask_size]
                prefix_primes[i+prime*mask_size] = (prefix_add_number + prime) % prefix_primes[i+prime*mask_size]
    return prefix_primes[:length+2] + [0]

def good_pairs(N, M, P, A, B, prefix_primes):
    ways_to_choose_B = defaultdict(int)
    prefix_sum = [0] * (len(prefix_primes))
    found = 0
    for b in B:
        if is_prime(b) or b in prefix_primes:
            continue
        mask = 0
        s = b
        while s % P == 0:
            s //= P
        if (b * s - 1) % pow(P, M) == 0:
            continue
        for p in range(1, P + 1):
            if b % p == 0:
                mask = bin(p).count('1')
                break
        if mask == 0:
            mask_p = 0
        else:
            mask_p = (2 * prefix_sum[mask]) % P
        prefix_sum[mask] = int((prefix_primes[mask] - mask_p) % P) + M
        ways_to_choose_B[p] = (prefix_sum[(mask+1) % P] - max(prefix_sum[(mask + M) % P] - prefix_sum[mask], 0)) % P
        found += ways_to_choose_B[p] + max(prefix_sum[mask] - prefix_sum[p % P], 0) >= 1
        mask += 1
    return found

