from collections import defaultdict

def maxSubsequenceSum(sequence, m):
    n = len(sequence)
    dp = [[0] * (n - m + 1) for _ in range(m)]

    for i in range(n - m + 1):
        prefix_sum = 0
        for j in range(n - m + 1):
            prefix_sum += sequence[i + j]
            dp[i][j] = max(prefix_sum - prefix_sum // 2, prefix_sum - prefix_sum // 2 - dp[i][j - 1] if j > 0 else 0)

    return max(dp[i][n - m + 1 - j] for i in range(m) for j in range(n - m + 1))

