def find_ideal_path(city, roads):
    visited = {city}
    queue = collections.deque([city])
    while queue:
        current = queue.popleft()
        for neighbor in roads[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return visited

