            if (x, y) in [(0, 0), (0, 1), (0, 5), (1, 0), (1, 6), (5, 0), (5, 1), (6, 0)]:
                row.append('Q')
            else:
                row.append('.')
        board.append(row)
    used_positions = set()
    knights_count = 0
    free_positions = ((x, y) for y in range(8) for x in range(8) if board[y][x] == '.')

    while knights_count < n:
        for position in free_positions:
            if position not in used_positions:
                used_positions.add(position)
                knights_count += 1
                yield position
                if knights_count >= n:
                    break
        for position in used_positions:
            if board[position[1]][position[0]] != 'Q':
                used_positions.remove(position)
                break

    free_positions = ((x, y) for y in range(8) for x in range(8) if board[y][x] == '.' and (x, y) not in used_positions)

    while knights_count < n:
        for position in free_positions:
            if position not in used_positions:
                used_positions.add(position)
                knights_count += 1
                yield position
                break

