    if x == y:
        return 1, y
    edges = {}
    for i in range(2, x + 1):
        # We can calculate gcd with GCD function, but because they can be prime, Efritovsky helped us with this function
        while y % gcd(i, y) == 0:
            edges[abs(gcd(i, y) - x)] = y - gcd(i, y)
