def find_center(graph, k):
    def dfs(node, parent, depth, best):
        nonlocal max_depth
        children = len(graph[node])
        if children == 0:
            max_depth = max(max_depth, depth)
            return
        for next_node in graph[node]:
            if next_node == parent:
                continue
            get_max_depth(graph, next_node, depth + 1, best)
        return max_depth

    max_depth = 0
    best = 0
    visit_set = set()
    for node in graph:
        if node not in visit_set:
            get_max_depth(graph, node, 0, best)
            visit_set.add(node)
            dfs(node, -1, 0, max_depth)

    return best

def add_shortcuts(graph, max_depth, k):
    best = find_center(graph, k)
    centers = []
    for node in graph:
        if len(graph[node]) == 2:
            centers.append(node)

    shortcuts_added = 0
    for center in centers:
        shortncodes = []
        for neighbor in graph[center]:
            if len(graph[neighbor]) == 1 and neighbor not in centers:
                shortncodes.append((center, neighbor))
        shortcuts_added += len(shortncodes)
        if k <= max_depth:
            break
        elif max_depth > k:
            break
        else:
            for (d1, d2) in shortncodes:
                shortened_diameter = max_depth + 1
                for node in graph[d1]:
                    if node != d2:
                        new_diameter = dfs(graph, d1, d2, node, 2, shortened_diameter)
                        if new_diameter < shortened_diameter:
                            shortened_diameter = new_diameter
                if len(graph[d1]) == 1:
                    add_shortcuts(graph, shortened_diameter, k)

    min_shortcuts_needed = k - (max_depth + len(centers))
    if min_shortcuts_needed > 0:
        return (min_shortcuts_needed, max_depth)
    else:
        return 0, max_depth

