from bisect import bisect_right

def solve(n, k, nums):
    prefix_sums = [0]
    for num in nums:
        prefix_sums.append(prefix_sums[-1] + num)

    dp = [[-1] * (k+1) for _ in range(n+1)]

    for i in range(1, n+1):
        dp[i][0] = 0
        for j in range(1, k+1):
            dp[i][j] = dp[i-1][j]
            if j == 1:
                dp[i][j] = max(dp[i][j], prefix_sums[i] - prefix_sums[bisect_right(prefix_sums, prefix_sums[i-1])])
            else:
                for mid in range(1, j//2 + 1):
                    x = prefix_sums[i] - (prefix_sums[bisect_right(prefix_sums, prefix_sums[i-1]) - mid])
                    y = prefix_sums[bisect_right(prefix_sums, prefix_sums[i]) - mid] - prefix_sums[bisect_left(prefix_sums, prefix_sums[i-1]) - mid]
                    dp[i][j] = max(dp[i][j], dp[bisect_right(prefix_sums, prefix_sums[i-1]) - mid + 1][j - mid] + x - y)

    return dp[n][k]

