def calculate_f_k(b, n, m, p):
    power_b = [v % p for v in b]
    factors = [1] * len(b) * 2

    # Compute (f_i^b_j) % p
    for i in range(1, len(b) + 1):
        for j in range(len(b)):
            if b[j] == 1 and i <= len(b):
                factors[i] = (factors[i] * power_b[j]) % p
            elif i - j > len(b):
                break
            else:
                factors[i * 2 - j - 1] = (factors[i * 2 - j - 1] * power_b[j]) % p

    # Multiply factors and modulo p
    result = 1
    for factor in factors:
        result = (result * factor) % p

    if result % p == m:
        return result
    else:
        return -1

